      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: alpha
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stride_x
      integer(kind=c_int), value :: batch_count
      integer(kind(rocblas_status_)) :: rocblas_sscal_strided_batched
    end function

  end interface



