  !< @{
  !< \brief <b> BLAS Level 1 API </b>
  !< 
  !< \details
  !< dot(u)  performs the dot product of vectors x and y:
  !< 
  !<     result = x * y;
  !< 
  !< dotc  performs the dot product of the conjugate of complex vector x and complex vector y.
  !< 
  !<     result = conjugate (x) * y;
  !< 
  !< @param[in]
  !< handle    [rocblas_handle]
  !<           handle to the rocblas library context queue.
  !< @param[in]
  !< n         [rocblas_int]
  !<           the number of elements in x and y.
  !< @param[in]
  !< x         device pointer storing vector x.
  !< @param[in]
  !< incx      [rocblas_int]
  !<           specifies the increment for the elements of y.
  !< @param[in]
  !< y         device pointer storing vector y.
  !< @param[in]
  !< incy      [rocblas_int]
  !<           specifies the increment for the elements of y.
  !< @param[in, out]
  !< result
  !<           device pointer or host pointer to store the dot product.
  !<           return is 0.0 if n <= 0.
  !< 
  !<  ******************************************************************
  interface rocblas_sdot
    function rocblas_sdot_(handle,n,x,incx,y,incy,result) bind(c, name="rocblas_sdot")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      type(c_ptr), value :: result
