  !< @{
  !< \brief <b> BLAS Level 1 API </b>
  !< 
  !< \details
  !< dot_strided_batched(u)  performs a batch of dot products of vectors x and y:
  !< 
  !<     result_i = x_i * y_i;
  !< 
  !< dotc_strided_batched  performs a batch of dot products of the conjugate of complex vector x and complex vector y
  !< 
  !<     result_i = conjugate (x_i) * y_i;
  !<     where (x_i, y_i) is the i-th instance of the batch.
  !<     x_i and y_i are vectors, for i = 1, ..., batch_count.
  !< 
  !< @param[in]
  !< handle    [rocblas_handle]
  !<           handle to the rocblas library context queue.
  !< @param[in]
  !< n         [rocblas_int]
  !<           the number of elements in each x_i and y_i.
  !< @param[in]
  !< x         device pointer to the first vector (x_1) in the batch.
  !< @param[in]
  !< incx      [rocblas_int]
  !<           specifies the increment for the elements of each x_i.
  !< @param[in]
  !< stridex     [rocblas_stride]
  !<             stride from the start of one vector (x_i) and the next one (x_i+1).
  !< @param[in]
  !< y         device pointer to the first vector (y_1) in the batch.
  !< @param[in]
  !< incy      [rocblas_int]
  !<           specifies the increment for the elements of each y_i.
  !< @param[in]
  !< stridey     [rocblas_stride]
  !<             stride from the start of one vector (y_i) and the next one (y_i+1).
  !< @param[in]
  !< batch_count [rocblas_int]
  !<             number of instances in the batch.
  !< @param[in, out]
  !< result
  !<           device array or host array of batch_count size to store the dot products of each batch.
  !<           return 0.0 for each element if n <= 0.
  !< 
  !<  ******************************************************************
  interface rocblas_sdot_strided_batched
    function rocblas_sdot_strided_batched_(handle,n,x,incx,stridex,y,incy,stridey,batch_count,result) bind(c, name="rocblas_sdot_strided_batched")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stridex
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      integer(kind=c_long), value :: stridey
      integer(kind=c_int), value :: batch_count
      type(c_ptr), value :: result
      integer(kind(rocblas_status_)) :: rocblas_sdot_strided_batched
    end function

  end interface



