  !< @{
  !< \brief <b> BLAS Level 1 API </b>
  !< 
  !< \details
  !< swap_strided_batched interchanges vectors x_i and y_i, for i = 1 , ... , batch_count:
  !< 
  !<     y_i := x_i;
  !<     x_i := y_i
  !< 
  !< @param[in]
  !< handle    [rocblas_handle]
  !<           handle to the rocblas library context queue.
  !< @param[in]
  !< n         [rocblas_int]
  !<           the number of elements in each x_i and y_i.
  !< @param[in, out]
  !< x         device pointer to the first vector x_1.
  !< @param[in]
  !< incx      [rocblas_int]
  !<           specifies the increment for the elements of x.
  !< @param[in]
  !< stridex   [rocblas_stride]
  !<           stride from the start of one vector (x_i) and the next one (x_i+1).
  !<           There are no restrictions placed on stride_x. However, ensure that stride_x is of appropriate size. For a typical
  !<           case this means stride_x >= n * incx.
  !< @param[in, out]
  !< y         device pointer to the first vector y_1.
  !< @param[in]
  !< incy      [rocblas_int]
  !<           specifies the increment for the elements of y.
  !< @param[in]
  !< stridey   [rocblas_stride]
  !<           stride from the start of one vector (y_i) and the next one (y_i+1).
  !<           There are no restrictions placed on stride_x. However, ensure that stride_y is of appropriate size. For a typical
  !<           case this means stride_y >= n * incy. stridey should be non zero.
  !<  @param[in]
  !<  batch_count [rocblas_int]
  !<              number of instances in the batch.
  !< 
  !<  ******************************************************************
  interface rocblas_sswap_strided_batched
    function rocblas_sswap_strided_batched_(handle,n,x,incx,stridex,y,incy,stridey,batch_count) bind(c, name="rocblas_sswap_strided_batched")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stridex
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      integer(kind=c_long), value :: stridey
      integer(kind=c_int), value :: batch_count
      integer(kind(rocblas_status_)) :: rocblas_sswap_strided_batched
    end function

  end interface



