  !< @{
  !< \brief <b> BLAS Level 1 API </b>
  !< 
  !< \details
  !< axpy   computes constant alpha multiplied by vector x, plus vector y:
  !< 
  !<     y := alpha * x + y
  !< 
  !< @param[in]
  !< handle    [rocblas_handle]
  !<           handle to the rocblas library context queue.
  !< @param[in]
  !< n         [rocblas_int]
  !<           the number of elements in x and y.
  !< @param[in]
  !< alpha     device pointer or host pointer to specify the scalar alpha.
  !< @param[in]
  !< x         device pointer storing vector x.
  !< @param[in]
  !< incx      [rocblas_int]
  !<           specifies the increment for the elements of x.
  !< @param[out]
  !< y         device pointer storing vector y.
  !< @param[in, out]
  !< incy      [rocblas_int]
  !<           specifies the increment for the elements of y.
  !< 
  !<  ******************************************************************
  interface rocblas_saxpy
    function rocblas_saxpy_(handle,n,alpha,x,incx,y,incy) bind(c, name="rocblas_saxpy")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: alpha
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
