  !< @{
  !< \brief <b> BLAS Level 1 API </b>
  !< 
  !< \details
  !< rotm applies the modified Givens rotation matrix defined by param to vectors x and y.
  !< 
  !< @param[in]
  !< handle  [rocblas_handle]
  !<         handle to the rocblas library context queue.
  !< @param[in]
  !< n       [rocblas_int]
  !<         number of elements in the x and y vectors.
  !< @param[in, out]
  !< x       device pointer storing vector x.
  !< @param[in]
  !< incx    [rocblas_int]
  !<         specifies the increment between elements of x.
  !< @param[in, out]
  !< y       device pointer storing vector y.
  !< @param[in]
  !< incy    [rocblas_int]
  !<         specifies the increment between elements of y.
  !< @param[in]
  !< param   device vector or host vector of 5 elements defining the rotation.
  !< 
  !<     param[0] = flag
  !<     param[1] = H11
  !<     param[2] = H21
  !<     param[3] = H12
  !<     param[4] = H22
  !< 
  !<     The flag parameter defines the form of H:
  !< 
  !<     flag = -1 => H = ( H11 H12 H21 H22 )
  !<     flag =  0 => H = ( 1.0 H12 H21 1.0 )
  !<     flag =  1 => H = ( H11 1.0 -1.0 H22 )
  !<     flag = -2 => H = ( 1.0 0.0 0.0 1.0 )
  !< 
  !<     param may be stored in either host or device memory,
  !<     location is specified by calling rocblas_set_pointer_mode.
  !< 
  !<  ******************************************************************
  interface rocblas_srotm
    function rocblas_srotm_(handle,n,x,incx,y,incy,param) bind(c, name="rocblas_srotm")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: n
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      type(c_ptr), value :: param
      integer(kind(rocblas_status_)) :: rocblas_srotm
    end function

  end interface



