  !< @{
  !< \brief <b> BLAS Level 2 API </b>
  !< 
  !< \details
  !< ger_strided_batched,geru_strided_batched,gerc_strided_batched performs the matrix-vector operations:
  !< 
  !<     A_i := A_i + alpha*x_i*y_i**T, OR
  !<     A_i := A_i + alpha*x_i*y_i**H  for gerc
  !<     where (A_i, x_i, y_i) is the i-th instance of the batch.
  !<     alpha is a scalar, x_i and y_i are vectors and A_i is an
  !<     m by n matrix, for i = 1, ..., batch_count.
  !< 
  !< @param[in]
  !< handle    [rocblas_handle]
  !<           handle to the rocblas library context queue.
  !< @param[in]
  !< m         [rocblas_int]
  !<           the number of rows of each matrix A_i.
  !< @param[in]
  !< n         [rocblas_int]
  !<           the number of columns of each matrix A_i.
  !< @param[in]
  !< alpha
  !<           device pointer or host pointer to scalar alpha.
  !< @param[in]
  !< x         device pointer to the first vector (x_1) in the batch.
  !< @param[in]
  !< incx      [rocblas_int]
  !<           specifies the increments for the elements of each vector x_i.
  !< @param[in]
  !< stridex   [rocblas_stride]
  !<           stride from the start of one vector (x_i) and the next one (x_i+1).
  !<           There are no restrictions placed on stride_x. However, ensure that stride_x is of appropriate size. For a typical
  !<           case this means stride_x >= m * incx.
  !< @param[in, out]
  !< y         device pointer to the first vector (y_1) in the batch.
  !< @param[in]
  !< incy      [rocblas_int]
  !<           specifies the increment for the elements of each vector y_i.
  !< @param[in]
  !< stridey   [rocblas_stride]
  !<           stride from the start of one vector (y_i) and the next one (y_i+1).
  !<           There are no restrictions placed on stride_y. However, ensure that stride_y is of appropriate size. For a typical
  !<           case this means stride_y >= n * incy.
  !< @param[in, out]
  !< A         device pointer to the first matrix (A_1) in the batch.
  !< @param[in]
  !< lda       [rocblas_int]
  !<           specifies the leading dimension of each A_i.
  !< @param[in]
  !< strideA     [rocblas_stride]
  !<             stride from the start of one matrix (A_i) and the next one (A_i+1)
  !< @param[in]
  !< batch_count [rocblas_int]
  !<             number of instances in the batch.
  !< 
  !<  ******************************************************************
  interface rocblas_sger_strided_batched
    function rocblas_sger_strided_batched_(handle,m,n,alpha,x,incx,stridex,y,incy,stridey,A,lda,strideA,batch_count) bind(c, name="rocblas_sger_strided_batched")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
      type(c_ptr), value :: handle
      integer(kind=c_int), value :: m
      integer(kind=c_int), value :: n
      type(c_ptr), value :: alpha
      type(c_ptr), value :: x
      integer(kind=c_int), value :: incx
      integer(kind=c_long), value :: stridex
      type(c_ptr), value :: y
      integer(kind=c_int), value :: incy
      integer(kind=c_long), value :: stridey
      type(c_ptr), value :: A
      integer(kind=c_int), value :: lda
      integer(kind=c_long), value :: strideA
      integer(kind=c_int), value :: batch_count
      integer(kind(rocblas_status_)) :: rocblas_sger_strided_batched
    end function

  end interface



  interface rocblas_dger_strided_batched
    function rocblas_dger_strided_batched_(handle,m,n,alpha,x,incx,stridex,y,incy,stridey,A,lda,strideA,batch_count) bind(c, name="rocblas_dger_strided_batched")
