  interface rocsolver_cstein
    function rocsolver_cstein_(handle,n,D,E,nev,W,iblock,isplit,Z,ldz,ifail,info) bind(c, name="rocsolver_cstein")
      use iso_c_binding
      use hipfort_rocblas.h

      implicit none
