      integer(kind=c_long), value :: strideD
      type(c_ptr), value :: E
      integer(kind=c_long), value :: strideE
      type(c_ptr), value :: tauq
      integer(kind=c_long), value :: strideQ
      type(c_ptr), value :: taup
      integer(kind=c_long), value :: strideP
      integer(kind=c_int), value :: batch_count
      integer(kind(rocblas_status_)) :: rocsolver_dgebrd_strided_batched
    end function

  end interface



  interface rocsolver_cgebrd_strided_batched
    function rocsolver_cgebrd_strided_batched_(handle,m,n,A,lda,strideA,D,strideD,E,strideE,tauq,strideQ,taup,strideP,batch_count) bind(c, name="rocsolver_cgebrd_strided_batched")
