      integer(kind=c_int), value :: lda
      integer(kind=c_long), value :: strideA
      type(c_ptr), value :: ipiv
      integer(kind=c_long), value :: strideP
      type(c_ptr), value :: info
      integer(kind=c_int), value :: batch_count
