    function rocsolver_dgeblttrs_npvt_strided_batched_(handle,nb,nblocks,nrhs,A,lda,strideA,B,ldb,strideB,C,ldc,strideC,X,ldx,strideX,batch_count) bind(c, name="rocsolver_dgeblttrs_npvt_strided_batched")
