      integer(kind=c_int), value :: nrhs
      integer(kind=c_int), value :: nnzM
      type(c_ptr), value :: ptrM
      type(c_ptr), value :: indM
      type(c_ptr), value :: valM
      integer(kind=c_int), value :: nnzT
